import sys
import heapq

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def kruskal(n, edges):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    mst_edges = []
    total_weight = 0
    for weight, u, v in edges:
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            mst_edges.append((u, v, weight))
            total_weight += weight
    return mst_edges

def max_energy_for_corridors(n, m, corridors):
    edges = [(e, a, b) for a, b, e in corridors]
    edges.sort()
    mst_edges = kruskal(n, edges)
    mst_set = set((min(u, v), max(u, v)) for u, v, _ in mst_edges)
    result = [-1] * m
    max_energy = [0] * (n + 1)

    for i, (a, b, e) in enumerate(corridors):
        ab = (min(a, b), max(a, b))
        if ab in mst_set:
            result[i] = e
            max_energy[a] = max(max_energy[a], e)
            max_energy[b] = max(max_energy[b], e)

    for i, (a, b, e) in enumerate(corrigors):
        ab = (min(a, b), max(a, b"))
        if ab not in mst_set:
            result[i] = min(max_energy[a], max_energy[b])

    return result

